# Generates TweakClasses.h/.cpp and targets_tweaks.txt for the TweakFloatFunction subclasses from the RTTI table and the exe.
use strict;
chdir "../../.." or die;
my $exe = do { local $/; open my $f, "<:raw", "Exported/SQZ.EXE" or die; <$f> };
sub rva2off { my ($va) = @_; my $pe = unpack('V', substr($exe,0x3c,4)); my ($nsec,$opt) = unpack('x6 v x12 v', substr($exe,$pe,24)); my $base = unpack('V', substr($exe,$pe+24+28,4));
  for my $i (0..$nsec-1) { my ($vs,$va0,$rs,$rp) = unpack('x8 V V V V', substr($exe,$pe+24+$opt+$i*40,40)); my $r = $va-$base; return $rp+$r-$va0 if $r >= $va0 && $r < $va0+$vs; } die }
sub cstr { my ($va) = @_; my $o = rva2off($va); return unpack('Z*', substr($exe,$o,64)); }
sub bytes { my ($va,$n) = @_; return substr($exe, rva2off($va), $n); }
open R, "<tools/rtti.tsv"; my @cls;
while (<R>) { chomp; my @f = split /\t/; next unless $f[0] =~ /^\.\?AV(\w+Function)\@\@$/; my $cn = $1; next unless ($f[3] // '') =~ /TweakFloatFunction/; my @s = map { hex } split /;/, $f[4]; push @cls, [$cn, hex($f[1]), @s]; }
my %fsz; { open my $ff, "<nm/fns_all.txt" or die; while (<$ff>) { $fsz{hex($1)} = $2 if /^([0-9a-f]+) size=(\d+)/ } }
sub sizearg { my ($a) = @_; return "" if exists $fsz{$a}; for my $s (keys %fsz) { return " " . ($s + $fsz{$s} - $a) if $s < $a && $a < $s + $fsz{$s} } return "" }
my (@h, @c, @t);
for my $c (@cls) {
  my ($n, $vt, $sdd, $exec, $create, $print, $name, $make, $argc) = @$c;
  my $nb = bytes($name, 5); my $str = (unpack('C', $nb) == 0xb8) ? cstr(unpack('V', substr($nb,1,4))) : '?';
  my $ab = bytes($argc, 5); my $cnt = (unpack('C', $ab) == 0xb8) ? unpack('V', substr($ab,1,4)) : 0;
  (my $short = $n) =~ s/Function$//;
  push @h, "class $n : public TweakFloatFunction {\npublic:\n    virtual int Execute(ScriptCall *a, int extra);          // " . sprintf("0x%x", $exec) . "\n    virtual const char *Name();                             // " . sprintf("0x%x", $name) . "\n    virtual TweakFloatFunction *Make();                     // " . sprintf("0x%x", $make) . "\n    virtual int ArgCount();                                 // " . sprintf("0x%x", $argc) . "\n};\n";
  push @c, "const char *$n\::Name() { return \"$str\"; }\nint $n\::ArgCount() { return $cnt; }\nTweakFloatFunction *$n\::Make() { return new $n; }\n";
  my $q = '^' . chr(92) . '?';
  push @t, sprintf($q . "Name\@$n  %x %s_name\n" . $q . "ArgCount\@$n  %x %s_argc\n" . $q . "Make\@$n  %x %s_make" . sizearg($make) . "\n" . $q . chr(92) . "?_G$n  %x %s_sdd auto\n", $name, $short, $argc, $short, $make, $short, $sdd, $short);
}
open H, ">Repo/src/FunctionTweak/TweakClasses.h"; print H "// The twenty TweakFloatFunction subclasses (generated by gen.pl from the RTTI table).\n#pragma once\n#include \"FunctionTweak/FunctionTweak.h\"\n\n", join("\n", @h); close H;
open C, ">Repo/src/FunctionTweak/TweakClasses.cpp"; print C "// Small slots of the TweakFloatFunction subclasses (generated by gen.pl): Name, ArgCount, Make, and the implicit scalar-deleting destructor.\n#include \"FunctionTweak/TweakClasses.h\"\n\n", join("\n", @c); close C;
open T, ">Repo/src/FunctionTweak/targets_tweaks.txt"; print T @t; close T;
print scalar(@cls), " classes\n";
